// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0));
        c.Initialized();
        bool reverted;
        try c.SetLogFile(logAddr) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }
}
